(7351206, 1149562, 147314, '<td valign="top">Congrats on the Red, Paul. Even Expert Editing is in your expertise now. Well done!!</td>', 'Congrats on the Red, Paul. Even Expert Editing is in your expertise now. Well done!!', '2015-05-18 05:37:22.000000', NULL, 0),
(7351207, 1149593, 147314, '<td valign="top">Congrats on a well-deserved Blue, Christophe. Again a beautiful creation. But even more than the image I was touched by your contemplation about why people act like they do, without any respect towards persons, animals or objects of nature. It is one of the things that keeps me busy day after day and also the reason I''d like to hide myself from this world more and more, seeking refuge in the most remote parts of Scotland when possible!<br/>I hope you can find comfort in being with your wife and daughter, together enjoying the beautiful things that nature provides. And please keep on with your refreshing and beautiful reproduction of this world in your images. Thank you!</td>', 'Congrats on a well-deserved Blue, Christophe. Again a beautiful creation. But even more than the image I was touched by your contemplation about why people act like they do, without any respect towards persons, animals or objects of nature. It is one of the things that keeps me busy day after day and also the reason I''d like to hide myself from this world more and more, seeking refuge in the most remote parts of Scotland when possible!I hope you can find comfort in being with your wife and daughter, together enjoying the beautiful things that nature provides. And please keep on with your refreshing and beautiful reproduction of this world in your images. Thank you!', '2015-05-18 05:51:21.000000', NULL, 0),
(7351208, 1149576, 147314, '<td valign="top">Congrats on the Yellow, it''s a great commandment.</td>', 'Congrats on the Yellow, it''s a great commandment.', '2015-05-18 05:54:34.000000', NULL, 0),
(7351210, 1149632, 147314, '<td valign="top">Congrats on the HM, Rob. And don''t tell me this is another never finished project in UAE ;-)</td>', 'Congrats on the HM, Rob. And don''t tell me this is another never finished project in UAE ;-)', '2015-05-18 05:56:20.000000', NULL, 0),
